output[0, 9:18] = 6
output[19, 0:9] = 6

# Piecewise boundary
for r in range(H):
    for c in range(W):
        if (r, c) in [(0, c) for c in range(9, 18)] or \
           (r, c) in [(19, c) for c in range(0, 9)]:
            continue
        if r <= 6:
            threshold = 14
        elif r <= 9:
            threshold = 15
        else:
            threshold = 11
        if c >= threshold:
            output[r, c] = 9
        else:
            output[r, c] = 4

